1	//! # 第八章：并发
2	//!
3	//! 本章在第七章"进程间通信与信号"的基础上，引入了 **线程** 和 **同步原语**。
4	//!
5	//! ## 核心概念
6	//!
7	//! ### 1. 线程（Thread）
8	//!
9	//! 将原来的"进程"拆分为两个独立的抽象：
10	//! - **Process（进程）**：管理共享资源（地址空间、文件描述符表、同步原语列表、信号）
11	//! - **Thread（线程）**：管理执行状态（上下文、TID）
12	//!
13	//! 同一进程的多个线程共享地址空间，但各自有独立的用户栈和执行上下文。
14	//!
15	//! ### 2. 同步原语
16	//!
17	//! - **Mutex（互斥锁）**：保证临界区互斥访问
18	//! - **Semaphore（信号量）**：P/V 操作，支持计数型资源管理
19	//! - **Condvar（条件变量）**：配合互斥锁使用，支持线程等待/唤醒
20	//!
21	//! ### 3. 线程阻塞
22	//!
23	//! 当线程尝试获取已被占用的锁/信号量时，内核将其标记为**阻塞态**，
24	//! 从就绪队列中移除。当持有者释放资源时，唤醒等待队列中的线程。
25	//!
26	//! ## 与第七章的主要区别
27	//!
28	//! | 特性 | 第七章 | 第八章 |
29	//! |------|--------|--------|
30	//! | 执行单元 | Process（进程即线程） | Thread（线程），Process 仅管理资源 |
31	//! | 管理器 | PManager | PThreadManager（进程 + 线程双层管理） |
32	//! | 同步 | 无 | Mutex / Semaphore / Condvar |
33	//! | task-manage feature | `proc` | `thread` |
34	//! | 新增依赖 | — | tg-sync |
35	//!
36	//! 教程阅读建议：
37	//!
38	//! - 先看 `rust_main`：抓住“线程创建 + 双层管理 + trap 分发”总流程；
39	//! - 再看主循环中 `SEMAPHORE_DOWN/MUTEX_LOCK/CONDVAR_WAIT` 分支：理解阻塞态切换；
40	//! - 最后看 `impls`：把线程、信号、同步三类系统调用如何交织串起来。
41	
42	// 不使用标准库
43	#![no_std]
44	// 不使用默认 main 入口
45	#![no_main]
46	#![cfg_attr(target_arch = "riscv64", deny(warnings, missing_docs))]
47	#![cfg_attr(not(target_arch = "riscv64"), allow(dead_code, unused_imports))]
48	
49	/// 文件系统模块：easy-fs 封装 + 统一 Fd 枚举
50	mod fs;
51	/// 进程与线程模块：Process（资源容器）和 Thread（执行单元）
52	mod process;
53	/// 处理器模块：PROCESSOR 全局管理器（PThreadManager）
54	mod processor;
55	/// VirtIO 块设备驱动
56	mod virtio_block;
57	/// 死锁检测
58	mod deadlock;
59	
60	#[macro_use]
61	extern crate tg_console;
62	
63	#[macro_use]
64	extern crate alloc;
65	
66	use crate::{
67	    fs::{read_all, FS},
68	    impls::{Sv39Manager, SyscallContext},
69	    process::{Process, Thread},
70	    processor::{ProcManager, ProcessorInner, ThreadManager},
71	};
72	use alloc::alloc::alloc;
73	use core::{alloc::Layout, cell::UnsafeCell, mem::MaybeUninit};
74	use impls::Console;
75	pub use processor::PROCESSOR;
76	use riscv::register::*;
77	#[cfg(not(target_arch = "riscv64"))]
78	use stub::Sv39;
79	use tg_console::log;
80	use tg_easy_fs::{FSManager, OpenFlags};
81	use tg_kernel_context::foreign::MultislotPortal;
82	#[cfg(target_arch = "riscv64")]
83	use tg_kernel_vm::page_table::Sv39;
84	use tg_kernel_vm::{
85	    page_table::{MmuMeta, VAddr, VmFlags, VmMeta, PPN, VPN},
86	    AddressSpace,
87	};
88	use tg_sbi;
89	use tg_signal::SignalResult;
90	use tg_syscall::Caller;
91	use tg_task_manage::ProcId;
92	use xmas_elf::ElfFile;
93	
94	/// 构建 VmFlags
95	#[cfg(target_arch = "riscv64")]
96	const fn build_flags(s: &str) -> VmFlags<Sv39> {
97	    VmFlags::build_from_str(s)
98	}
99	
100	/// 解析 VmFlags
101	#[cfg(target_arch = "riscv64")]
102	fn parse_flags(s: &str) -> Result<VmFlags<Sv39>, ()> {
103	    s.parse()
104	}
105	
106	#[cfg(not(target_arch = "riscv64"))]
107	use stub::{build_flags, parse_flags};
108	
109	// 内核入口，栈 = 32 页 = 128 KiB。
110	//
111	// 这里不再调用 tg_linker::boot0! 宏，避免外部已发布版本与 Rust 2024
112	// 在属性语义上的兼容差异影响本 crate 的发布校验。
113	#[cfg(target_arch = "riscv64")]
114	#[unsafe(naked)]
115	#[unsafe(no_mangle)]
116	#[unsafe(link_section = ".text.entry")]
117	unsafe extern "C" fn _start() -> ! {
118	    const STACK_SIZE: usize = 32 * 4096;
119	    #[unsafe(link_section = ".boot.stack")]
120	    static mut STACK: [u8; STACK_SIZE] = [0u8; STACK_SIZE];
121	
122	    core::arch::naked_asm!(
123	        "la sp, {stack} + {stack_size}",
124	        "j  {main}",
125	        stack = sym STACK,
126	        stack_size = const STACK_SIZE,
127	        main = sym rust_main,
128	    )
129	}
130	
131	/// 物理内存容量 = 48 MiB
132	const MEMORY: usize = 48 << 20;
133	/// 异界传送门所在虚页
134	const PROTAL_TRANSIT: VPN<Sv39> = VPN::MAX;
135	
136	/// 内核地址空间的全局存储
137	struct KernelSpace {
138	    inner: UnsafeCell<MaybeUninit<AddressSpace<Sv39, Sv39Manager>>>,
139	}
140	
141	unsafe impl Sync for KernelSpace {}
142	
143	impl KernelSpace {
144	    const fn new() -> Self {
145	        Self {
146	            inner: UnsafeCell::new(MaybeUninit::uninit()),
147	        }
148	    }
149	
150	    unsafe fn write(&self, space: AddressSpace<Sv39, Sv39Manager>) {
151	        unsafe { *self.inner.get() = MaybeUninit::new(space) };
152	    }
153	
154	    unsafe fn assume_init_ref(&self) -> &AddressSpace<Sv39, Sv39Manager> {
155	        unsafe { &*(*self.inner.get()).as_ptr() }
156	    }
157	}
158	
159	/// 内核地址空间全局实例
160	static KERNEL_SPACE: KernelSpace = KernelSpace::new();
161	
162	/// VirtIO MMIO 设备地址范围
163	pub const MMIO: &[(usize, usize)] = &[(0x1000_1000, 0x00_1000)];
164	
165	/// 内核主函数
166	///
167	/// 与第七章相比：
168	/// - 新增 `init_thread`（线程系统调用）和 `init_sync_mutex`（同步原语系统调用）
169	/// - 使用 `PThreadManager`（双层管理器）替代 `PManager`
170	/// - 初始化时同时创建 Process 和 Thread
171	/// - 主循环中新增**线程阻塞**处理（SEMAPHORE_DOWN/MUTEX_LOCK/CONDVAR_WAIT）
172	extern "C" fn rust_main() -> ! {
173	    let layout = tg_linker::KernelLayout::locate();
174	    // 步骤 1：BSS 清零
175	    unsafe { layout.zero_bss() };
176	    // 步骤 2：控制台和日志
177	    tg_console::init_console(&Console);
178	    tg_console::set_log_level(option_env!("LOG"));
179	    tg_console::test_log();
180	    // 步骤 3：堆分配器
181	    tg_kernel_alloc::init(layout.start() as _);
182	    unsafe {
183	        tg_kernel_alloc::transfer(core::slice::from_raw_parts_mut(
184	            layout.end() as _,
185	            MEMORY - layout.len(),
186	        ))
187	    };
188	    // 步骤 4：异界传送门
189	    let portal_size = MultislotPortal::calculate_size(1);
190	    let portal_layout = Layout::from_size_align(portal_size, 1 << Sv39::PAGE_BITS).unwrap();
191	    let portal_ptr = unsafe { alloc(portal_layout) };
192	    assert!(portal_layout.size() < 1 << Sv39::PAGE_BITS);
193	    // 步骤 5：内核地址空间
194	    kernel_space(layout, MEMORY, portal_ptr as _);
195	    // 步骤 6：异界传送门初始化
196	    let portal = unsafe { MultislotPortal::init_transit(PROTAL_TRANSIT.base().val(), 1) };
197	    // 步骤 7：系统调用初始化
198	    tg_syscall::init_io(&SyscallContext);
199	    tg_syscall::init_process(&SyscallContext);
200	    tg_syscall::init_scheduling(&SyscallContext);
201	    tg_syscall::init_clock(&SyscallContext);
202	    tg_syscall::init_signal(&SyscallContext);
203	    tg_syscall::init_thread(&SyscallContext);       // 本章新增：线程系统调用
204	    tg_syscall::init_sync_mutex(&SyscallContext);   // 本章新增：同步原语系统调用
205	    // 步骤 8：加载 initproc（返回 Process + Thread）
206	    let initproc = read_all(FS.open("initproc", OpenFlags::RDONLY).unwrap());
207	    if let Some((process, thread)) = Process::from_elf(ElfFile::new(initproc.as_slice()).unwrap()) {
208	        // 初始化双层管理器：ProcManager（进程）+ ThreadManager（线程）
209	        PROCESSOR.get_mut().set_proc_manager(ProcManager::new());
210	        PROCESSOR.get_mut().set_manager(ThreadManager::new());
211	        let (pid, tid) = (process.pid, thread.tid);
212	        PROCESSOR
213	            .get_mut()
214	            .add_proc(pid, process, ProcId::from_usize(usize::MAX));
215	        PROCESSOR.get_mut().add(tid, thread, pid);
216	    }
217	
218	    // ─── 主调度循环 ───
219	    loop {
220	        let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
221	        if let Some(task) = unsafe { (*processor).find_next() } {
222	            unsafe { task.context.execute(portal, ()) };
223	
224	            match scause::read().cause() {
225	                // ─── 系统调用 ───
226	                scause::Trap::Exception(scause::Exception::UserEnvCall) => {
227	                    use tg_syscall::{SyscallId as Id, SyscallResult as Ret};
228	                    let ctx = &mut task.context.context;
229	                    ctx.move_next();
230	                    let id: Id = ctx.a(7).into();
231	                    let args = [ctx.a(0), ctx.a(1), ctx.a(2), ctx.a(3), ctx.a(4), ctx.a(5)];
232	                    let syscall_ret = tg_syscall::handle(Caller { entity: 0, flow: 0 }, id, args);
233	
234	                    // ─── 信号处理 ───
235	                    let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
236	                    match current_proc.signal.handle_signals(ctx) {
237	                        SignalResult::ProcessKilled(exit_code) => unsafe {
238	                            (*processor).make_current_exited(exit_code as _)
239	                        },
240	                        _ => match syscall_ret {
241	                            Ret::Done(ret) => match id {
242	                                Id::EXIT => unsafe { (*processor).make_current_exited(ret) },
243	                                // ─── 本章新增：同步原语阻塞处理 ───
244	                                // 当 semaphore_down / mutex_lock / condvar_wait 返回 -1 时，
245	                                // 表示资源不可用，将当前线程标记为阻塞态
246	                                Id::SEMAPHORE_DOWN | Id::MUTEX_LOCK | Id::CONDVAR_WAIT => {
247	                                    let ctx = &mut task.context.context;
248	                                    *ctx.a_mut(0) = ret as _;
249	                                    if ret == -1 {
250	                                        // 阻塞：从就绪队列移除，等待资源释放后唤醒
251	                                        unsafe { (*processor).make_current_blocked() };
252	                                    } else {
253	                                        // 成功获取：正常挂起（时间片轮转）
254	                                        unsafe { (*processor).make_current_suspend() };
255	                                    }
256	                                }
257	                                _ => {
258	                                    let ctx = &mut task.context.context;
259	                                    *ctx.a_mut(0) = ret as _;
260	                                    unsafe { (*processor).make_current_suspend() };
261	                                }
262	                            },
263	                            Ret::Unsupported(_) => {
264	                                log::info!("id = {id:?}");
265	                                unsafe { (*processor).make_current_exited(-2) };
266	                            }
267	                        },
268	                    }
269	                }
270	                e => {
271	                    log::error!("unsupported trap: {e:?}");
272	                    unsafe { (*processor).make_current_exited(-3) };
273	                }
274	            }
275	        } else {
276	            println!("no task");
277	            break;
278	        }
279	    }
280	
281	    tg_sbi::shutdown(false)
282	}
283	
284	/// panic 处理
285	#[panic_handler]
286	fn panic(info: &core::panic::PanicInfo) -> ! {
287	    println!("{info}");
288	    tg_sbi::shutdown(true)
289	}
290	
291	/// 建立内核地址空间（与前几章相同）
292	fn kernel_space(layout: tg_linker::KernelLayout, memory: usize, portal: usize) {
293	    let mut space = AddressSpace::new();
294	    for region in layout.iter() {
295	        log::info!("{region}");
296	        use tg_linker::KernelRegionTitle::*;
297	        let flags = match region.title {
298	            Text => "X_RV",
299	            Rodata => "__RV",
300	            Data | Boot => "_WRV",
301	        };
302	        let s = VAddr::<Sv39>::new(region.range.start);
303	        let e = VAddr::<Sv39>::new(region.range.end);
304	        space.map_extern(
305	            s.floor()..e.ceil(),
306	            PPN::new(s.floor().val()),
307	            build_flags(flags),
308	        )
309	    }
310	    let s = VAddr::<Sv39>::new(layout.end());
311	    let e = VAddr::<Sv39>::new(layout.start() + memory);
312	    log::info!("(heap) ---> {:#10x}..{:#10x}", s.val(), e.val());
313	    space.map_extern(
314	        s.floor()..e.ceil(),
315	        PPN::new(s.floor().val()),
316	        build_flags("_WRV"),
317	    );
318	    space.map_extern(
319	        PROTAL_TRANSIT..PROTAL_TRANSIT + 1,
320	        PPN::new(portal >> Sv39::PAGE_BITS),
321	        build_flags("__G_XWRV"),
322	    );
323	    println!();
324	    for (base, len) in MMIO {
325	        let s = VAddr::<Sv39>::new(*base);
326	        let e = VAddr::<Sv39>::new(*base + *len);
327	        log::info!("MMIO range -> {:#10x}..{:#10x}", s.val(), e.val());
328	        space.map_extern(
329	            s.floor()..e.ceil(),
330	            PPN::new(s.floor().val()),
331	            build_flags("_WRV"),
332	        );
333	    }
334	    unsafe { satp::set(satp::Mode::Sv39, 0, space.root_ppn().val()) };
335	    unsafe { KERNEL_SPACE.write(space) };
336	}
337	
338	/// 将异界传送门映射到用户地址空间
339	fn map_portal(space: &AddressSpace<Sv39, Sv39Manager>) {
340	    let portal_idx = PROTAL_TRANSIT.index_in(Sv39::MAX_LEVEL);
341	    space.root()[portal_idx] = unsafe { KERNEL_SPACE.assume_init_ref() }.root()[portal_idx];
342	}
343	
344	/// 各种接口库的实现
345	///
346	/// 与第七章相比，本章新增了：
347	/// - `Thread` trait（thread_create/gettid/waittid）
348	/// - `SyncMutex` trait（mutex/semaphore/condvar 系统调用）
349	/// - 所有操作通过 `ProcessorInner`（PThreadManager）进行双层管理
350	mod impls {
351	    use crate::{
352	        build_flags,
353	        fs::{read_all, Fd, FS},
354	        processor::ProcessorInner,
355	        Sv39, Thread, PROCESSOR,
356	    };
357	    use alloc::sync::Arc;
358	    use alloc::{alloc::alloc_zeroed, string::String, vec::Vec};
359	    use core::{alloc::Layout, ptr::NonNull};
360	    use spin::Mutex;
361	    use tg_console::log;
362	    use tg_easy_fs::{make_pipe, FSManager, OpenFlags, UserBuffer};
363	    use tg_kernel_vm::{
364	        page_table::{MmuMeta, Pte, VAddr, VmFlags, VmMeta, PPN, VPN},
365	        PageManager,
366	    };
367	    use tg_signal::SignalNo;
368	    use tg_sync::{Condvar, Mutex as MutexTrait, MutexBlocking, Semaphore};
369	    use tg_syscall::*;
