530	    /// 进程管理系统调用
531	    impl Process for SyscallContext {
532	        #[inline]
533	        fn exit(&self, _caller: Caller, exit_code: usize) -> isize { exit_code as isize }
534	
535	        /// fork：创建子进程（返回 Process + Thread）
536	        fn fork(&self, _caller: Caller) -> isize {
537	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
538	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
539	            let parent_pid = current_proc.pid;
540	            let (proc, mut thread) = current_proc.fork().unwrap();
541	            let pid = proc.pid;
542	            *thread.context.context.a_mut(0) = 0 as _;
543	            unsafe {
544	                (*processor).add_proc(pid, proc, parent_pid);
545	                (*processor).add(thread.tid, thread, pid);
546	            }
547	            pid.get_usize() as isize
548	        }
549	
550	        /// exec：从文件系统加载新程序
551	        fn exec(&self, _caller: Caller, path: usize, count: usize) -> isize {
552	            const READABLE: VmFlags<Sv39> = build_flags("RV");
553	            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
554	            current.address_space
555	                .translate(VAddr::new(path), READABLE)
556	                .map(|ptr| unsafe {
557	                    core::str::from_utf8_unchecked(core::slice::from_raw_parts(ptr.as_ptr(), count))
558	                })
559	                .and_then(|name| FS.open(name, OpenFlags::RDONLY))
560	                .map_or_else(
561	                    || {
562	                        log::error!("unknown app, select one in the list: ");
563	                        FS.readdir("").unwrap().into_iter().for_each(|app| println!("{app}"));
564	                        println!();
565	                        -1
566	                    },
567	                    |fd| { current.exec(ElfFile::new(&read_all(fd)).unwrap()); 0 },
568	                )
569	        }
570	
571	        fn wait(&self, _caller: Caller, pid: isize, exit_code_ptr: usize) -> isize {
572	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
573	            let current = unsafe { (*processor).get_current_proc().unwrap() };
574	            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
575	            if let Some((dead_pid, exit_code)) =
576	                unsafe { (*processor).wait(ProcId::from_usize(pid as usize)) }
577	            {
578	                if let Some(mut ptr) = current.address_space
579	                    .translate::<i32>(VAddr::new(exit_code_ptr), WRITABLE)
580	                { unsafe { *ptr.as_mut() = exit_code as i32 }; }
581	                return dead_pid.get_usize() as isize;
582	            } else { return -1; }
583	        }
584	
585	        fn getpid(&self, _caller: Caller) -> isize {
586	            PROCESSOR.get_mut().get_current_proc().unwrap().pid.get_usize() as _
587	        }
588	    }
