846	            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
847	            let id = if let Some(id) = current_proc.condvar_list.iter().enumerate()
848	                .find(|(_, item)| item.is_none()).map(|(id, _)| id)
