872	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
873	            let current = unsafe { (*processor).current().unwrap() };
874	            let tid = current.tid;
875	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
876	
877	            let tid_usize = tid.get_usize();
878	            if let Some(m_list) = current_proc.mutex_allocations.get_mut(&tid_usize) {
879	                if let Some(pos) = m_list.iter().position(|&x| x == mutex_id) {
880	                    m_list.remove(pos);
881	                }
882	            }
883	
884	            let condvar = Arc::clone(current_proc.condvar_list[condvar_id].as_ref().unwrap());
885	            let mutex = Arc::clone(current_proc.mutex_list[mutex_id].as_ref().unwrap());
886	            let (flag, waking_tid) = condvar.wait_with_mutex(tid, mutex);
887	
888	            if let Some(waking_tid) = waking_tid {
889	                // The waking thread from condvar implicitly tries to acquire the mutex again!
890	                // Since it's done by `wait_with_mutex` inside sync, we might need to be careful here.
891	                // Wait! In tg_sync, `wait_with_mutex` unlocks the mutex and adds tid to condvar wait_queue.
892	                // But it does NOT re-acquire the mutex yet. The user program must call mutex_lock again!
893	                // Let's check `condvar.rs` implementation later. For now, just re-enqueue waking_tid.
894	                unsafe { (*processor).re_enque(waking_tid); }
895	            }
896	            if !flag { -1 } else { 0 }
