225	
226	/// 系统调用处理结果
227	enum SyscallResult {
228	    /// 系统调用完成，继续执行用户程序
229	    Done,
230	    /// 用户程序请求退出，附带退出码
231	    Exit(usize),
232	    /// 不支持的系统调用
233	    Error(SyscallId),
234	}
235	
236	/// U-Mode 异常求助与系统调用捕获总线
237	///
238	/// 当用户态程序触发内部异常或调用 `ecall` 期望调用 S-Mode 资源响应服务时，CPU 临时陷入特权管理流并切入此分发器。
239	/// 此函数的运行目标在于严格保护内核态控制数据的情况下赋予用户态所需的安全访问：
240	/// 1. **状态留存与请求剖析**：从保存在特权堆栈的用户恢复寄存器状态对象 `LocalContext` 内，抽取请求标识（`a7` 取 `Syscall id`）与业务参数（`a0`-`a5`）。
241	/// 2. **特权降维操作与授权**：比如处理本章额外追加的 233 专属图形 Syscall 时，内核利用早先下放的强校验全局 GPU 控制句柄与指针组为其在幕后绘图而严防 U-Mode 将不符规的内存越权指派给 DMA。
242	/// 3. **结果指派与返回重置**：调用相应受信任接口，处理结束后返回系统反馈放回 `a0` 作为成功或错误参数反馈。最后推进地址 `sepc`，恢复调用时 U 态指令留痕处用于后续程序重新推演流控。
243	fn handle_syscall(ctx: &mut LocalContext) -> SyscallResult {
244	    use tg_syscall::{SyscallId as Id, SyscallResult as Ret};
245	
246	    let id_val = ctx.a(7); // 系统调用号
247	
248	    // 处理绘制七巧板子块的专属 syscall
249	    if id_val == 233 {
250	        let part_idx = ctx.a(0); // 期望渲染第几块
251	        unsafe {
252	            let gpu_ptr = core::ptr::addr_of_mut!(GPU_DEV);
253	            if let Some(gpu) = (*gpu_ptr).as_mut() {
254	                let fb = core::slice::from_raw_parts_mut(FB_PTR, FB_LEN);
255	                let num_o = tangram::TANGRAM_O.len();
256	                let num_s = tangram::TANGRAM_S.len();
257	                
258	                let mut valid = false;
259	                if part_idx < num_o {
260	                    let poly = &tangram::TANGRAM_O[part_idx];
261	                    tangram::fill_polygon(poly.vertices, poly.color, fb, GPU_WIDTH);
262	                    valid = true;
263	                } else if part_idx < num_o + num_s {
264	                    let s_idx = part_idx - num_o;
265	                    let poly = &tangram::TANGRAM_S[s_idx];
266	                    tangram::fill_polygon(poly.vertices, poly.color, fb, GPU_WIDTH);
267	                    valid = true;
268	                }
269	                
270	                if valid {
271	                    let _ = gpu.flush(); // 通知 DMA 同步物理显存显示
272	                }
273	            }
274	        }
275	        
276	        *ctx.a_mut(0) = 0; // 返回 0 表成功
277	        ctx.move_next();   // 步进 sepc
278	        return SyscallResult::Done;
279	    }
280	
281	    // a7 寄存器存放 syscall ID
282	    let id = ctx.a(7).into();
283	    // a0-a5 寄存器存放系统调用参数
284	    let args = [ctx.a(0), ctx.a(1), ctx.a(2), ctx.a(3), ctx.a(4), ctx.a(5)];
285	
286	    match tg_syscall::handle(Caller { entity: 0, flow: 0 }, id, args) {
287	        Ret::Done(ret) => match id {
288	            Id::EXIT => SyscallResult::Exit(ctx.a(0)),
289	            _ => {
290	                // 将返回值写入 a0
291	                *ctx.a_mut(0) = ret as _;
292	                // sepc += 4，使 sret 后从 ecall 的下一条指令继续执行
293	                ctx.move_next();
294	                SyscallResult::Done
295	            }
296	        },
297	        Ret::Unsupported(id) => SyscallResult::Error(id),
298	    }
299	}
